function validate([queryIP]) {
  if (typeof queryIP !== 'string') return 'queryIP must be a string.';
  if (!/^[A-Za-z0-9.:]*$/.test(queryIP)) return 'queryIP may only use letters, digits, dots and colons.';
  return null;
}

