function validIPAddress(queryIP) {
  const isDecimalField = (field) => {
    if (field.length === 0 || field.length > 3) return false;
    if (field.length > 1 && field[0] === '0') return false;
    for (const ch of field) {
      if (ch < '0' || ch > '9') return false;
    }
    return Number(field) <= 255;
  };

  const hexDigits = '0123456789abcdefABCDEF';
  const isHexField = (field) => {
    if (field.length === 0 || field.length > 4) return false;
    for (const ch of field) {
      if (!hexDigits.includes(ch)) return false;
    }
    return true;
  };

  const ipv4Fields = queryIP.split('.');
  if (ipv4Fields.length === 4 && ipv4Fields.every(isDecimalField)) {
    return 'IPv4';
  }
  const ipv6Fields = queryIP.split(':');
  if (ipv6Fields.length === 8 && ipv6Fields.every(isHexField)) {
    return 'IPv6';
  }
  return 'Neither';
}

