function validIPAddress(queryIP) {
  const octet = '(25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9][0-9]|[0-9])';
  const v4 = new RegExp('^' + octet + '(\\.' + octet + '){3}$');
  const v6 = /^[0-9a-fA-F]{1,4}(:[0-9a-fA-F]{1,4}){7}$/;
  if (v4.test(queryIP)) return 'IPv4';
  if (v6.test(queryIP)) return 'IPv6';
  return 'Neither';
}

