  const pick = (list) => list[Math.floor(rand() * list.length)];
  const hex = '0123456789abcdefABCDEF';
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const noise = hex + 'gGjxXzZ.:';
  const decimalField = (clean) => {
    const r = clean ? 0 : rand();
    if (r < 0.5) return String(pick([0, 1, 9, 10, 99, 100, 199, 200, 249, 250, 255, int(0, 255)]));
    if (r < 0.62) return String(int(256, 999));
    if (r < 0.74) return '0' + String(int(0, 99));
    if (r < 0.82) return '';
    if (r < 0.92) return String(int(0, 99)) + pick(letters);
    return String(int(1000, 99999));
  };
  const hexField = (clean) => {
    const r = clean ? 0 : rand();
    const length = r < 0.6 ? int(1, 4) : r < 0.75 ? 0 : r < 0.88 ? 5 : int(1, 4);
    let field = '';
    for (let k = 0; k < length; k++) field += pick(hex);
    if (r >= 0.88 && field.length > 0) field = field.slice(0, -1) + pick('ghjkxyzGXZ');
    return field;
  };
  const address = (count4, count6) => {
    const clean = rand() < 0.45;
    if (rand() < 0.5) {
      const count = clean || rand() < 0.7 ? 4 : count4;
      return Array.from({ length: count }, () => decimalField(clean)).join('.');
