    const count = clean || rand() < 0.7 ? 8 : count6;
    return Array.from({ length: count }, () => hexField(clean)).join(':');
  };
  if (size === 'small') {
    if (rand() < 0.15) {
      let s = '';
      const n = int(0, 12);
      for (let k = 0; k < n; k++) s += pick(noise);
      return [s];
    }
    return [address(pick([1, 3, 5]), pick([1, 7, 9]))];
  }
  const mode = int(0, 3);
  if (mode === 0) return [address(pick([3, 5]), pick([7, 9]))];
  if (mode === 1) {
