    return [parts.join(':')];
  }
  if (mode === 2) return ['1' + '0'.repeat(int(100, 5000)) + '.1.1.1'];
  let s = '';
  for (let k = 0; k < 10000; k++) s += pick(noise);
  return [s];
}
